PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profiles(user_id INTEGER PRIMARY KEY,first_name TEXT NOT NULL,last_name TEXT NOT NULL,scout_name TEXT,member_id TEXT NOT NULL UNIQUE,unit TEXT,patrol TEXT,role TEXT NOT NULL DEFAULT 'member',photo_url TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS members(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,first_name TEXT NOT NULL,last_name TEXT NOT NULL,scout_name TEXT,member_id TEXT NOT NULL UNIQUE,unit TEXT,patrol TEXT,role TEXT NOT NULL DEFAULT 'member',photo_url TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS activities(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT,date TEXT NOT NULL,time TEXT,location TEXT,leader_member_id INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(leader_member_id) REFERENCES members(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS activity_participants(activity_id INTEGER NOT NULL,member_id INTEGER NOT NULL,PRIMARY KEY(activity_id,member_id),FOREIGN KEY(activity_id) REFERENCES activities(id) ON DELETE CASCADE,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS conversations(id INTEGER PRIMARY KEY AUTOINCREMENT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS conversation_members(conversation_id INTEGER NOT NULL,member_id INTEGER NOT NULL,PRIMARY KEY(conversation_id,member_id),FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS message_attachments(id INTEGER PRIMARY KEY AUTOINCREMENT,message_id INTEGER,type TEXT NOT NULL,url TEXT NOT NULL,size INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(message_id) REFERENCES messages(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT,conversation_id INTEGER NOT NULL,sender_id INTEGER NOT NULL,receiver_id INTEGER NOT NULL,message_type TEXT NOT NULL DEFAULT 'text',content TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,read_at TEXT,client_id TEXT UNIQUE,FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,FOREIGN KEY(sender_id) REFERENCES members(id) ON DELETE CASCADE,FOREIGN KEY(receiver_id) REFERENCES members(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_messages_conversation ON messages(conversation_id,id);
CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT,priority TEXT NOT NULL DEFAULT 'normal',due_date TEXT,assigned_member_id INTEGER,completed INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(assigned_member_id) REFERENCES members(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS badges(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,description TEXT,criteria TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS member_badges(member_id INTEGER NOT NULL,badge_id INTEGER NOT NULL,awarded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(member_id,badge_id),FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE,FOREIGN KEY(badge_id) REFERENCES badges(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS skills(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,description TEXT);
CREATE TABLE IF NOT EXISTS member_skills(member_id INTEGER NOT NULL,skill_id INTEGER NOT NULL,progress INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(member_id,skill_id),FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE,FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS announcements(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,content TEXT NOT NULL,author_user_id INTEGER,date TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(author_user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS settings(user_id INTEGER PRIMARY KEY,theme TEXT NOT NULL DEFAULT 'dark',language TEXT NOT NULL DEFAULT 'ht',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
